public ListNode ReverseRec(ListNode head) {
    if (head == null || head.next == null) return head;   // пусто или один узел
    var newHead = ReverseRec(head.next);   // хвост развёрнут, его голова — новая голова
    head.next.next = head;                 // бывший второй узел указывает на нас
    head.next = null;                      // мы теперь последние
    return newHead;
}

